'use strict';
const MANAGEMENT_UI5={bind,organizationView,boardView,storesView,leadershipView,procurementView,help,performanceDetail5,performanceView};
TITLES.management='Řídicí přehled & chytré vedení';
let managementStore5=null,managementFilter5='all';
function managementView(){const m=state.management5,p=m.policy,e=state.organization.executives.purchasing,latest=m.history.at(-1),stores=state.stores.filter(s=>!s.franchise);if(!stores.some(s=>s.id===managementStore5))managementStore5=stores[0]?.id||null;const s=stores.find(s=>s.id===managementStore5),sp=s?.management5,alerts=managementExceptions5(),decisions=m.decisions.filter(r=>managementFilter5==='all'||r.kind===managementFilter5).slice(-30).reverse();return `<div class="view-toolbar"><p class="intro">Nastav hranice vedení a řeš výjimky. Odhady slouží k rozhodnutí; skutečný výsledek je z odehraného provozu.</p><button class="soft" id="managementReport5">Report boardu</button></div><div class="report-overview5">${metric('VÝJIMKY',alerts.length,'Problémy a návrhy k rozhodnutí')}${metric('ČEKAJÍCÍ NÁKUPY',m.proposals.filter(x=>x.status==='pending').length,'Větší částky schvaluješ ty')}${metric('CÍLE BOARDU',latest?latest.achieved+' / 5':'—',latest?'Skutečný týden '+latest.week:'Odehraj první týden')}${metric('ŘEDITEL NÁKUPU',esc(e.manager?.name||'Neobsazeno'),e.manager?money(e.manager.salary*1.35)+'/týden':'Role v Obchodu')}</div><section class="card" style="margin-top:24px"><h2>Co potřebuje pozornost</h2>${alerts.length?alerts.slice(0,40).map(a=>`<div class="news"><span class="news-icon ${a.severity===2?'bad':''}">${a.severity===2?'!':'•'}</span><div style="flex:1"><strong>${esc(a.target)}</strong><small>${esc(a.text)}</small></div><button class="soft mini" data-management-goto5="${a.view}" data-target="${a.id}">Otevřít správu</button></div>`).join(''):empty('Bez naléhavé výjimky ve sledovaných oblastech.')}<p class="sub">Přehled sleduje nákup, faktury, zásoby, obsluhu a ztrátové kavárny. Další provozní krize najdeš ve správě problémů.</p><button class="soft" data-goto="crises">Problémy a pravomoci</button></section><div class="split" style="margin-top:24px"><section class="card"><h2>Mandát nákupu</h2><p class="sub">Ředitel potřebuje místo v kanceláři, vlastní mzdu a pracovníka Obchodu. Splatnost navíc vyžaduje Finance. Objednává pouze pro zapnutou automatickou výrobu.</p><button class="soft" data-goto="organization">Obsadit ředitele a oddělení</button><div class="fields">${field('Limit nových závazků / týden',input('purchaseBudget5',p.budget,0,100000,1000))}${field('Schválit ručně nad částku',input('purchaseApproval5',p.approval,0,200000,1000))}${field('Hotovostní rezerva / týdny',input('purchaseReserve5',p.reserve,1,8,1))}${field('Zelená zásoba navíc / týdny',input('purchaseCover5',p.cover,1,6,1))}${field('Minimální kvalita partie',input('purchaseQuality5',p.quality,25,99,1))}${field('Strategie',`<select id="purchaseStrategy5">${[['cost','Cena'],['reliable','Spolehlivost'],['quality','Kvalita']].map(([id,label])=>option(id,label,p.strategy)).join('')}</select>`)}${field('Platba',`<select id="purchaseTerms5">${option(0,'Předem',p.terms)}${option(2,'Dva týdny po doručení',p.terms)}</select>`)}</div><label class="checkbox-line"><input type="checkbox" id="purchaseEnabled5" ${p.enabled?'checked':''}> Povolit automatické objednávky v mandátu</label><button class="primary" id="purchasePolicySave5">Uložit mandát nákupu</button><p class="sub">Rozpočet počítá celou cenu i u úvěru. Sklad a již objednané zásilky se odečítají; jedna potřeba města se nezdvojí s více pražírnami. Nákupy mimo limit nebo nad schvalovací částku čekají na tebe. Výpočet je zásobovací odhad; kapacita výroby a budoucí poptávka se mohou změnit.</p></section><section class="card"><h2>Chytré vedení kavárny</h2>${s?`${field('Kavárna',`<select id="smartStore5">${stores.map(s=>option(s.id,loc(s.id).city+' · '+loc(s.id).name,managementStore5)).join('')}</select>`)}<p class="sub">Odpovědnost: ${esc(owner5(s)?.person.name||'Zakladatel')}. Vedení porovná povolené ceny ±5 Kč, marketing ±500 Kč a rozložení směn. Ruční rozpis a vypnuté pravomoci respektuje.</p><div class="fields">${field('Hlavní cíl',`<select id="smartGoal5">${[['profit','Zisk'],['service','Obsluha hostů'],['quality','Kvalita']].map(([id,label])=>option(id,label,sp.goal)).join('')}</select>`)}${field('Marketing nejvýše / týden',input('smartBudget5',sp.budget,0,10000,500))}${field('Rezerva pro zvýšení marketingu',input('smartReserve5',sp.reserve,1,8,1))}</div><label class="checkbox-line"><input type="checkbox" id="smartEnabled5" ${sp.enabled?'checked':''}> Zapnout porovnávání místo dosavadních pravidel</label><button class="primary" id="smartSave5">Uložit řízení kavárny</button><button class="soft" data-goto="people">Pravomoci ceny, marketingu a týmu</button><p class="sub">Místní odhad používá skutečné menu, směny, tým a fronty, ale předpokládá dostatek kávy. Nevytváří zaměstnance ani neslibuje zisk. Aktuální sklad, výroba, konkurence a další změny se projeví ve skutečném výsledku.</p>`:empty('Nejdřív otevři vlastní kavárnu.')}</section></div><section class="card" style="margin-top:24px"><h2>Nákupy ke schválení</h2>${m.proposals.filter(x=>x.status==='pending').map(x=>`<div class="news"><div style="flex:1"><strong>${esc(x.name)} · ${esc(SUPPLIERS5[x.data.supplier].name)}</strong><small>${x.data.kg} kg · ${esc(ORIGINS[x.data.origin].name)} · závazek ${money(x.quote.cost)} · T${x.quote.due}</small><p>${esc(x.reason)}</p><div class="actions"><button class="soft" data-management-refresh5="${x.id}">Aktualizovat nabídku</button><button class="primary" data-management-approve5="${x.id}">Schválit nákup</button><button class="quiet" data-management-reject5="${x.id}">Odmítnout</button></div></div></div>`).join('')||empty('Žádný nákup čekající na schválení.')}<p class="sub">Schválení dovolí přesně tuto objednávku i nad automatický limit. Návrh ověří autora, cenu, kapacitu a rezervu. Po změně firmy aktualizuj nabídku.</p></section><section class="card" style="margin-top:24px"><h2>Cíle boardu a skutečný výsledek</h2><div class="fields">${field('Výsledek firmy / týden alespoň',input('boardProfit5',m.goals.profit,0,10000000,1000))}${field('Kvalita obsloužených hostů alespoň',input('boardQuality5',m.goals.quality,25,99,1))}${field('Rezerva alespoň / týdny',input('boardReserve5',m.goals.reserve,1,8,1))}${field('Počet kaváren alespoň',input('boardStores5',m.goals.stores,1,LOCATIONS.length,1))}${field('Neobsloužení nejvýše / %',input('boardLost5',m.goals.lost*100,0,100,1))}</div><label class="checkbox-line"><input type="checkbox" id="boardEnabled5" ${m.boardEnabled?'checked':''}> Použít cíle kvality, rezervy, zisku a obsluhy při hlasování</label><button class="primary" id="boardGoalsSave5">Uložit cíle dalších týdnů</button>${latest?rows([['Výsledek firmy',money(latest.values.profit)+' / cíl '+money(latest.goals.profit)],['Kvalita obsloužených',latest.values.quality===null?'Bez obsloužených hostů':number(latest.values.quality,1)+' / cíl '+latest.goals.quality],['Hotovostní rezerva',number(latest.values.reserve,1)+' / cíl '+latest.goals.reserve+' týdnů'],['Velikost sítě',latest.values.stores+' / cíl '+latest.goals.stores],['Neobsloužení hosté',latest.values.lost===null?'Bez návštěv':number(latest.values.lost*100,1)+' % / limit '+number(latest.goals.lost*100)+' %']]):empty('První hodnocení vznikne po odehraném týdnu.')}<p class="sub">Historie uchovává tehdejší cíle. Změna cíle nepřepíše minulé hodnocení. Aktivní mandát může změnit hlasy o investici, růstu nebo dividendě. Většinový zakladatel si ponechává možnost prosadit návrh. Cíl velikosti sítě neblokuje její růst. Board hodnotí celou firmu; nezaměňuj její výsledek s přínosem jednotlivého manažera.</p></section><section class="card" style="margin-top:24px"><div class="card-head"><h2>Rozhodnutí, odhad a skutečnost</h2><select id="managementFilter5">${[['all','Všechna rozhodnutí'],['store','Kavárny'],['purchase','Nákup'],['director','Ředitelé oddělení']].map(([id,label])=>option(id,label,managementFilter5)).join('')}</select></div>${decisions.map(r=>`<article class="mandate-result5"><strong>T${r.week} · ${esc(r.author)}</strong><p>${esc(r.action)}</p><p class="sub">${esc(r.reason)}</p>${r.kind==='store'&&r.options?'<details><summary>Posuzované varianty</summary>'+rows(r.options.map(o=>[esc(o.action),money(o.profit)+' · '+number(o.served)+' hostů · kvalita '+number(o.quality,1)]))+'</details>':''}${r.kind==='store'?rows([['Odhad provozu před změnou',money(r.baseline.profit)+' · '+number(r.baseline.served)+' hostů'],['Odhad zvoleného provozu',money(r.expected.profit)+' · '+number(r.expected.served)+' hostů'],['Skutečný provoz týdne',r.actual?money(r.actual.profit)+' · '+r.actual.served+' hostů · kvalita '+number(r.actual.quality,1):'Čeká na odehraný provoz']]):r.kind==='purchase'?rows([['Schválená hodnota',money(r.cost)],['Očekávání',r.expected.kg+' kg · T'+r.expected.due+' · kvalita alespoň '+r.expected.quality],['Skutečné doručení',r.actual?r.actual.kg+' kg · T'+r.actual.week+' · kvalita '+r.actual.quality+' · '+(r.actual.onTime?'v termínu':'po termínu'):'Zásilka na cestě']]):rows([['Schválená částka',money(r.cost)],['Výsledek celé firmy',r.actual?money(r.actual.profit)+' (bez určení příčinného přínosu zásahu)':'Čeká na odehraný týden']])}</article>`).join('')||empty('Po aktivaci mandátu a odehrání týdne uvidíš rozhodnutí.')}<p class="sub">Posledních 300 záznamů; zde nejvýše 30. Odhady jsou uložené před zásahem, skutečnost po týdnu nebo doručení. Pozdější změny je nepřepisují.</p></section>`;}
organizationView=function(){return '<div class="actions"><button class="soft" data-goto="management">Řídicí přehled, mandát nákupu a skutečné výsledky</button></div>'+MANAGEMENT_UI5.organizationView();};
boardView=function(){const h=state.management5.history.at(-1);return `<section class="card" style="margin-bottom:24px"><h2>Pět měřitelných cílů vedení</h2><p>${h?'Týden '+h.week+': splněno '+h.achieved+' z 5 cílů.':'Zisk, kvalita, hotovostní rezerva, růst a obsluha.'}</p><button class="soft" data-goto="management">Cíle, výjimky a rozhodnutí</button></section>`+MANAGEMENT_UI5.boardView();};
storesView=function(){return '<div class="actions"><button class="soft" data-goto="management">Nastavit chytré vedení kaváren</button></div>'+MANAGEMENT_UI5.storesView();};
leadershipView=function(){return '<div class="actions"><button class="soft" data-goto="management">Každodenní rozhodnutí a výjimky firmy</button></div>'+MANAGEMENT_UI5.leadershipView();};
procurementView=function(){return '<div class="actions"><button class="soft" data-goto="management">Předat nákup řediteli s limity</button></div>'+MANAGEMENT_UI5.procurementView();};
performanceView=function(){const html=MANAGEMENT_UI5.performanceView();return reportKind5==='governance'?html.replace('Soupeři mají vlastní ceny a baristy. Pobočky platí kávu, mzdy, nájem a provoz; skutečné obsloužené návštěvy omezí kapacita. Výsledek firmy navíc zahrnuje obchod, centrálu a úroky; investice snižují hotovost zvlášť. Jejich šarže a individuální fronty se nesimulují.','Board hodnotí pět tehdejších cílů. Schválené částky zahrnují nákupy zásob i splátky dluhu; nejde o součet provozních nákladů. Výsledek firmy nevyjadřuje příčinný přínos jednotlivého zásahu.'):html;};
performanceDetail5=function(id){MANAGEMENT_UI5.performanceDetail5(id);if(reportKind5==='governance'&&el('reportManage5'))el('reportManage5').onclick=()=>{el('modal').close();goto('management');};};
bind=function(){MANAGEMENT_UI5.bind();if(el('smartStore5'))el('smartStore5').onchange=()=>{managementStore5=el('smartStore5').value;render();};if(el('managementFilter5'))el('managementFilter5').onchange=()=>{managementFilter5=el('managementFilter5').value;render();};const num=id=>Number(el(id).value);if(el('purchasePolicySave5'))el('purchasePolicySave5').onclick=()=>act(()=>setPurchasingPolicy5({enabled:el('purchaseEnabled5').checked,budget:num('purchaseBudget5'),approval:num('purchaseApproval5'),reserve:num('purchaseReserve5'),cover:num('purchaseCover5'),quality:num('purchaseQuality5'),strategy:el('purchaseStrategy5').value,terms:num('purchaseTerms5')}),'Mandát nákupu uložen.');if(el('smartSave5'))el('smartSave5').onclick=()=>act(()=>setSmartManager5(managementStore5,{enabled:el('smartEnabled5').checked,budget:num('smartBudget5'),reserve:num('smartReserve5'),goal:el('smartGoal5').value}),'Cíl vedení kavárny uložen.');if(el('boardGoalsSave5'))el('boardGoalsSave5').onclick=()=>act(()=>setBoardGoals5({enabled:el('boardEnabled5').checked,profit:num('boardProfit5'),quality:num('boardQuality5'),reserve:num('boardReserve5'),stores:num('boardStores5'),lost:num('boardLost5')/100}),'Cíle boardu uložené pro další týdny.');on('[data-management-refresh5]',b=>act(()=>refreshManagementProposal5(b.dataset.managementRefresh5),'Nabídka aktualizována.'));on('[data-management-reject5]',b=>act(()=>decideManagementPurchase5(b.dataset.managementReject5,false),'Návrh odmítnut.'));on('[data-management-approve5]',b=>{const x=state.management5.proposals.find(x=>x.id===b.dataset.managementApprove5);confirmAction('Schválit přesnou objednávku?',esc(SUPPLIERS5[x.data.supplier].name)+' · '+x.data.kg+' kg · '+money(x.quote.cost)+'. Schválení překročí automatický limit, pokud je potřeba. '+(x.data.terms?'Faktura dva týdny po doručení.':'Platba předem.'),()=>decideManagementPurchase5(x.id,true),'Schválit');});on('[data-management-goto5]',b=>{if(b.dataset.managementGoto5==='live'&&b.dataset.target)liveStore=b.dataset.target;if(b.dataset.managementGoto5==='stores'&&b.dataset.target)filterCity=loc(b.dataset.target).city;goto(b.dataset.managementGoto5);});if(el('managementReport5'))el('managementReport5').onclick=()=>{reportKind5='governance';goto('performance');};};
help=function(){MANAGEMENT_UI5.help();const p=document.createElement('p');p.textContent='Edice 05.13: Řídicí přehled spojuje výjimky firmy, nákupní mandát, chytré vedení kaváren a pět cílů boardu. Ředitel nákupu je placená role v Obchodu; porovnává dodavatele pro skutečnou automatickou výrobu, odečítá sklad i zásilky a chrání kvalitu, rozpočet a rezervu. Větší závazek čeká na schválení. Chytré vedení kaváren je volitelné a respektuje vypnuté pravomoci i ruční rozpis. Místní odhad předpokládá dostatek kávy; report odděluje odhad, skutečný výsledek a výsledek celé firmy. Historické cíle ani rozhodnutí se po změně nastavení nepřepisují.';el('modalContent').append(p);};el('help').onclick=help;render();
